svg.script:
const svgRoot = document.currentScript.ownerSVGElement;
const teeth = [...svgRoot.querySelectorAll('.tooth')];

function selectTooth(tooth) {
  teeth.forEach(t => t.classList.remove('is-selected'));
  tooth.classList.add('is-selected');

  svgRoot.dispatchEvent(new CustomEvent('toothselect', {
    detail: { tooth: tooth.dataset.tooth },
    bubbles: true
  }));
}

teeth.forEach(tooth => {
  tooth.addEventListener('click', () => selectTooth(tooth));
  tooth.addEventListener('keydown', e => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      selectTooth(tooth);
    }
  });
});
